SELECT COUNT(DISTINCT struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR)) AS "count_result" FROM triples t0, triples t1, triples t2 WHERE t0.p = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#type' AND struct_pack(kind := 0::UTINYINT, value := t1.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t1.p = 'http://schema.org/text' AND t2.s = 'http://db.uwaterloo.ca/~galuc/wsdbm/User57094' AND t2.p = 'http://db.uwaterloo.ca/~galuc/wsdbm/likes' AND t2.o = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR)